# ── 解释器守卫：本脚本依赖 bash（数组 / [[ ]] / here-string 等）──
# 仅用 POSIX 语法编写，确保在 ash/dash 下也能解析并 fail-fast。
if [ -z "$BASH_VERSION" ]; then
    if command -v bash >/dev/null 2>&1; then
        exec bash "$0" "$@"
    fi
    echo "本脚本需要 bash 运行，当前 shell 不是 bash 且系统未安装 bash。"
    echo "请先安装 bash 后重试："
    echo "  Alpine:   apk add bash"
    echo "  OpenWrt:  opkg update && opkg install bash"
    echo "  Debian:   apt-get install -y bash"
    echo "  CentOS:   yum install -y bash"
    exit 1
fi

SSHD_CONFIG="/etc/ssh/sshd_config"
SSHD_MANAGED_BEGIN="# BEGIN VPS-TOOLS SSH SETTINGS"
SSHD_MANAGED_END="# END VPS-TOOLS SSH SETTINGS"
# Ubuntu 22.10+/Debian 新版 openssh-server 默认用 systemd socket 激活 sshd，
# sshd_config 的 Port 对监听端口不一定生效，必须显式覆盖 ssh.socket 的 ListenStream
SSHD_SOCKET_OVERRIDE_DIR="/etc/systemd/system/ssh.socket.d"
SSHD_SOCKET_OVERRIDE_FILE="$SSHD_SOCKET_OVERRIDE_DIR/99-vps-tools-port.conf"
# 优先使用 /root/.ssh/authorized_keys，兼容系统预装公钥路径
AUTH_KEYS="${HOME}/.ssh/authorized_keys"
[ "$(id -u)" = "0" ] && AUTH_KEYS="/root/.ssh/authorized_keys"
VPS_DATA_DIR="/var/lib/vps-tools"
# shellcheck disable=SC2034 # used by management modules in the concatenated release script
VPS_BACKUP_DIR="$VPS_DATA_DIR/backups"
# shellcheck disable=SC2034 # used by management modules in the concatenated release script
VPS_VERSION_DIR="$VPS_DATA_DIR/versions"
VPS_AUDIT_LOG="/var/log/vps-tools-audit.log"
VPS_BACKUP_KEEP="${VPS_BACKUP_KEEP:-20}"
case "$VPS_BACKUP_KEEP" in ''|*[!0-9]*) VPS_BACKUP_KEEP=20 ;; esac
[ "$VPS_BACKUP_KEEP" -ge 1 ] || VPS_BACKUP_KEEP=20

if [ -n "${NO_COLOR:-}" ] || [ "${TERM:-}" = "dumb" ] || [ ! -t 1 ]; then
    RED="" GREEN="" YELLOW="" BLUE="" CYAN="" BOLD="" DIM="" NC=""
else
    RED=$'\033[0;31m'
    GREEN=$'\033[0;32m'
    YELLOW=$'\033[1;33m'
    BLUE=$'\033[0;34m'
    CYAN=$'\033[0;36m'
    BOLD=$'\033[1m'
    DIM=$'\033[2m'
    NC=$'\033[0m'
fi

info()  { echo -e "  ${GREEN}✓${NC}  $1"; }
warn()  { echo -e "  ${YELLOW}!${NC}  $1"; }
error() { echo -e "  ${RED}×${NC}  $1"; }

vps_tools_ssh_connection() {
    local RAW="${VPS_TOOLS_SSH_CONNECTION:-${SSH_CONNECTION:-}}"
    local CLIENT_IP CLIENT_PORT SERVER_IP SERVER_PORT EXTRA
    [ -n "$RAW" ] || return 1
    read -r CLIENT_IP CLIENT_PORT SERVER_IP SERVER_PORT EXTRA <<< "$RAW"
    [ -z "$EXTRA" ] || return 1
    [ -n "$CLIENT_IP" ] && [ -n "$SERVER_IP" ] || return 1
    [ "${#CLIENT_IP}" -le 64 ] && [ "${#SERVER_IP}" -le 64 ] || return 1
    case "$CLIENT_IP$SERVER_IP" in *[!0-9A-Fa-f:.]*) return 1 ;; esac
    case "$CLIENT_PORT:$SERVER_PORT" in
        *[!0-9:]*|:*|*:) return 1 ;;
    esac
    [ "$CLIENT_PORT" -ge 1 ] 2>/dev/null && [ "$CLIENT_PORT" -le 65535 ] \
        && [ "$SERVER_PORT" -ge 1 ] 2>/dev/null && [ "$SERVER_PORT" -le 65535 ] \
        || return 1
    printf '%s %s %s %s\n' \
        "$CLIENT_IP" "$CLIENT_PORT" "$SERVER_IP" "$SERVER_PORT"
}

vps_tools_ssh_client_ip() {
    local CONNECTION CLIENT_IP
    CONNECTION=$(vps_tools_ssh_connection) || return 1
    read -r CLIENT_IP _ <<< "$CONNECTION"
    printf '%s\n' "$CLIENT_IP"
}

vps_tools_ssh_family() {
    local CLIENT_IP
    case "${VPS_TOOLS_SSH_FAMILY:-}" in
        4|6) printf '%s\n' "$VPS_TOOLS_SSH_FAMILY"; return 0 ;;
        "") ;;
        *) return 1 ;;
    esac
    CLIENT_IP=$(vps_tools_ssh_client_ip) || return 1
    case "$CLIENT_IP" in
        *:*) printf '6\n' ;;
        *.*) printf '4\n' ;;
        *) return 1 ;;
    esac
}

audit_action() {
    local ACTION="$1" RESULT="${2:-INFO}" SOURCE_IP="local"
    SOURCE_IP=$(vps_tools_ssh_client_ip 2>/dev/null || printf 'local')
    mkdir -p "$(dirname "$VPS_AUDIT_LOG")" 2>/dev/null || true
    printf '%s\t%s\t%s\t%s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$RESULT" "$SOURCE_IP" "$ACTION" \
        2>/dev/null >> "$VPS_AUDIT_LOG" || true
    chmod 600 "$VPS_AUDIT_LOG" 2>/dev/null || true
}

archive_gzip_decompress_bounded() {
    local INPUT="$1" OUTPUT="$2" MAX_COMPRESSED="$3" MAX_RAW="$4"
    local COMPRESSED_SIZE RAW_SIZE
    [[ "$MAX_COMPRESSED" =~ ^[1-9][0-9]*$ ]] \
        && [[ "$MAX_RAW" =~ ^[1-9][0-9]*$ ]] || return 1
    COMPRESSED_SIZE=$(stat -c '%s' "$INPUT" 2>/dev/null) || return 1
    [[ "$COMPRESSED_SIZE" =~ ^[0-9]+$ ]] \
        && [ "$COMPRESSED_SIZE" -le "$MAX_COMPRESSED" ] || return 1
    if ! command -v gzip >/dev/null 2>&1 \
        || ! command -v head >/dev/null 2>&1 \
        || ! (set -o pipefail; gzip -dc < "$INPUT" 2>/dev/null \
            | head -c "$((MAX_RAW + 1))" > "$OUTPUT"); then
        rm -f "$OUTPUT"
        return 1
    fi
    RAW_SIZE=$(stat -c '%s' "$OUTPUT" 2>/dev/null) || {
        rm -f "$OUTPUT"
        return 1
    }
    [[ "$RAW_SIZE" =~ ^[0-9]+$ ]] && [ "$RAW_SIZE" -le "$MAX_RAW" ] || {
        rm -f "$OUTPUT"
        return 1
    }
}

# 兼容 dumb 终端（OpenWrt / tmux 等不支持 clear 的环境）
safe_clear() {
    if [ -n "${TERM:-}" ] && [ "$TERM" != "dumb" ]; then
        clear 2>/dev/null || true
    fi
}

systemd_available() {
    command -v systemctl >/dev/null 2>&1 && [ -d /run/systemd/system ]
}

# 运行时探测 ssh.socket 是否是当前系统实际监听 SSH 连接的单元，
# 不按发行版/版本号猜测——不同 openssh-server 补丁版本行为并不一致
ssh_socket_activated() {
    systemd_available || return 1
    systemctl is-active --quiet ssh.socket 2>/dev/null
}

