# ── 可见宽度计算（用 python3，中文=2，ASCII=1）────────────
vis_len() {
    python3 -c "
import unicodedata, sys
s = sys.argv[1]
print(sum(2 if unicodedata.east_asian_width(c) in ('W','F') else 1 for c in s))
" "$1" 2>/dev/null || echo "${#1}"
}

# ── 响应式终端布局 ────────────────────────────────────────
BOX_W=64
UI_COMPACT=0
APP_UI_TITLE="VPS TOOLS"
APP_VERSION="V3.52.0"
APP_SUBTITLE="VPS 开荒脚本 · 银趴火山帮"

ui_refresh_dimensions() {
    local COLS="${COLUMNS:-}"
    if ! echo "$COLS" | grep -qE '^[0-9]+$'; then
        COLS=$(tput cols 2>/dev/null || echo 80)
    fi
    [ "$COLS" -gt 76 ] && COLS=76
    [ "$COLS" -lt 36 ] && COLS=36
    BOX_W=$COLS
    UI_COMPACT=0
    if [ "$BOX_W" -lt 66 ]; then UI_COMPACT=1; fi
}

ui_repeat() {
    local CHAR="$1" COUNT="$2" i
    for ((i=0; i<COUNT; i++)); do printf '%s' "$CHAR"; done
}

box_top() { ui_refresh_dimensions; printf '%s' "${BOLD}${CYAN}"; ui_repeat "━" "$BOX_W"; printf '%s\n' "$NC"; }
box_bot() { printf '%s' "${BOLD}${CYAN}"; ui_repeat "━" "$BOX_W"; printf '%s\n' "$NC"; }
box_sep() { printf '%s' "${DIM}${CYAN}"; ui_repeat "─" "$BOX_W"; printf '%s\n' "$NC"; }

# 居中标题行（只传纯文本，自动居中）
box_title() {
    local TEXT="$1"
    local LEN; LEN=$(vis_len "$TEXT")
    local INNER=$((BOX_W - 2))
    local PAD_TOTAL=$(( INNER - LEN ))
    [ "$PAD_TOTAL" -lt 0 ] && PAD_TOTAL=0
    local PAD_L=$(( PAD_TOTAL / 2 ))
    local PAD_R=$(( PAD_TOTAL - PAD_L ))
    printf '%*s' "$PAD_L" ''
    printf "${BOLD}${CYAN}%s${NC}" "$TEXT"
    printf '%*s' "$PAD_R" ''
    printf "\n"
}

# 普通内容行：PLAIN=纯文本(算宽度)  COLORED=带色码(显示用)
# 用法: box_line "纯文本" "带色码文本"
box_line() {
    local COLORED="${2:-$1}"
    echo -e "$COLORED"
}

# 空行
box_empty() {
    echo ""
}

# ── 内层分隔线（与主框线同宽对齐，dim 青，统一替代各处 seq 1 38）──
menu_div() { ui_refresh_dimensions; printf '%s' "${DIM}${CYAN}"; ui_repeat "─" "$BOX_W"; printf '%s\n' "$NC"; }

app_header_line() {
    echo -e "  ${DIM}${APP_UI_TITLE}  ·  ${APP_VERSION}${NC}"
}

app_subtitle_line() {
    echo -e "  ${BOLD}${CYAN}${APP_SUBTITLE}${NC}"
}

# ── 段标题（❯ 前缀，统一替代 [xxx] 方括号风格）──
menu_group() { echo -e "  ${CYAN}${BOLD}◆ ${1}${NC}"; }

# ── 菜单项（统一缩进与配色）。用法: menu_item "1" "SSH 工具集" [颜色]──
menu_item() {
    local KEY="$1" LABEL="$2" COL="${3:-$GREEN}"
    echo -e "    ${COL}${BOLD}${KEY}${NC}  ${LABEL}"
}

menu_pair() {
    local K1="$1" L1="$2" K2="${3:-}" L2="${4:-}" COL1="${5:-$GREEN}" COL2="${6:-$GREEN}"
    ui_refresh_dimensions
    if [ "$UI_COMPACT" = "1" ] || [ -z "$K2" ]; then
        menu_item "$K1" "$L1" "$COL1"
        [ -n "$K2" ] && menu_item "$K2" "$L2" "$COL2"
        return
    fi
    local LEFT="${K1}  ${L1}" TARGET=$((BOX_W / 2 - 3)) LEN PAD
    LEN=$(vis_len "$LEFT"); PAD=$((TARGET - LEN)); [ "$PAD" -lt 2 ] && PAD=2
    printf '    %s%s%s' "$COL1$BOLD" "$K1" "$NC"
    printf '  %s' "$L1"
    printf '%*s' "$PAD" ''
    printf '%s%s%s  %s\n' "$COL2$BOLD" "$K2" "$NC" "$L2"
}

status_dot() {
    local STATE="$1"
    case "$STATE" in
        active|running|yes|on|已启用|运行中) echo -e "${GREEN}●${NC}" ;;
        inactive|stopped|no|off|已停止) echo -e "${RED}●${NC}" ;;
        *) echo -e "${YELLOW}●${NC}" ;;
    esac
}

status_pair() {
    local L1="$1" V1="$2" S1="$3" L2="${4:-}" V2="${5:-}" S2="${6:-}" D1 D2 C1 C2
    case "$S1" in active|running|yes|on|已启用|运行中) C1="$GREEN" ;; inactive|stopped|no|off|已停止) C1="$RED" ;; *) C1="$YELLOW" ;; esac
    case "$S2" in active|running|yes|on|已启用|运行中) C2="$GREEN" ;; inactive|stopped|no|off|已停止) C2="$RED" ;; *) C2="$YELLOW" ;; esac
    D1="${C1}●${NC}"; D2="${C2}●${NC}"
    ui_refresh_dimensions
    if [ "$UI_COMPACT" = "1" ] || [ -z "$L2" ]; then
        echo -e "  $D1  ${DIM}${L1}${NC}  ${BOLD}${V1}${NC}"
        [ -n "$L2" ] && echo -e "  $D2  ${DIM}${L2}${NC}  ${BOLD}${V2}${NC}"
        return
    fi
    local PLAIN="●  ${L1}  ${V1}" TARGET=$((BOX_W / 2)) LEN PAD
    LEN=$(vis_len "$PLAIN"); PAD=$((TARGET - LEN)); [ "$PAD" -lt 2 ] && PAD=2
    echo -en "  $D1  ${DIM}${L1}${NC}  ${BOLD}${V1}${NC}"
    printf '%*s' "$PAD" ''
    echo -e "$D2  ${DIM}${L2}${NC}  ${BOLD}${V2}${NC}"
}

ui_hint() { echo -e "  ${DIM}› $1${NC}"; }
ui_prompt() { printf '  %s›%s %s' "$CYAN$BOLD" "$NC" "$1"; }
ui_pause() { echo ""; read -rp "$(ui_prompt '按 Enter 返回')" _; }
ui_continue() { echo ""; read -rp "$(ui_prompt '按 Enter 继续')" _; }


# ── 通用编辑器（兼容 Alpine/OpenWrt 等精简系统）────────────
get_editor() {
    for ed in nano vi vim; do
        command -v "$ed" &>/dev/null && echo "$ed" && return
    done
    echo "vi"  # 最后兜底，几乎所有系统都有 vi
}

open_editor() {
    local FILE="$1"
    local ED; ED=$(get_editor)
    if ! command -v "$ED" &>/dev/null; then
        # vi 也没有，尝试安装 nano
        warn "未找到编辑器，尝试安装 nano..."
        pkg_install nano &>/dev/null || pkg_install vim &>/dev/null || true
        ED=$(get_editor)
    fi
    "$ED" "$FILE"
}

# ── 确保 sysctl 可用（Alpine 需要 procps 或 sysctl 包）────
# 加载 nf_conntrack 模块（中转/落地机需要）
ensure_conntrack_module() {
    lsmod 2>/dev/null | grep -q "^nf_conntrack" && return 0
    modprobe nf_conntrack 2>/dev/null
}

ensure_sysctl() {
    command -v sysctl &>/dev/null && return 0
    warn "sysctl 未找到，正在安装..."
    if command -v apk &>/dev/null; then
        apk add --no-cache procps 2>/dev/null || apk add --no-cache sysctl 2>/dev/null || true
    else
        pkg_install procps 2>/dev/null || true
    fi
    command -v sysctl &>/dev/null && return 0
    error "sysctl 安装失败，请手动执行：apk add procps"
    return 1
}


# iptables/ip6tables 残留规则清理（卸载防火墙时使用）
clear_iptables_residue() {
    # 安全清理：只删除本脚本可能残留的规则，绝不 flush 全表、绝不改默认策略。
    # 旧版会 iptables -F + 设 ACCEPT，会瞬间裸奔并抹掉 NFT 转发/代理/用户自有规则。
    # ufw --force reset / firewalld 卸载本身已清掉各自规则，这里无需再 flush。
    local FAILED=no
    local NETFILTER_CMD CHECK_RC
    for NETFILTER_CMD in iptables ip6tables; do
        command -v "$NETFILTER_CMD" &>/dev/null || continue
        # 删除本脚本 SSH 放行可能残留的 INPUT ACCEPT 规则（逐条删，删到没有为止）
        local _p
        for _p in $(get_config "Port" 2>/dev/null) 22; do
            [ -n "$_p" ] || continue
            while true; do
                "$NETFILTER_CMD" -C INPUT -p tcp --dport "$_p" \
                    -j ACCEPT 2>/dev/null
                CHECK_RC=$?
                case "$CHECK_RC" in
                    0)
                        if ! "$NETFILTER_CMD" -D INPUT -p tcp \
                            --dport "$_p" -j ACCEPT 2>/dev/null; then
                            FAILED=yes
                            break
                        fi
                        ;;
                    1) break ;;
                    *) FAILED=yes; break ;;
                esac
            done
        done
    done
    if [ "$FAILED" = yes ]; then
        warn "本脚本的部分 iptables 残留规则未能删除"
        return 1
    fi
    info "已清理本脚本残留规则（未触碰默认策略与其它规则）"
}

# 统一标题栏
print_header() {
    safe_clear
    echo ""
    box_top
    app_header_line
    echo -e "  ${BOLD}${CYAN}$1${NC}"
    box_bot
    echo ""
}


# ── 兼容工具函数（支持 BusyBox / Alpine）─────────────────

# 替代 grep -oP '(?:maxrate|rate) \K\S+'
# 替代 grep -oE 'initcwnd [0-9]+' | awk '{print $2}'
# 检测服务管理器并重启 SSH
restart_ssh() {
    if systemd_available; then
        if ssh_socket_activated; then
            # socket 激活时，只重启 ssh.service 不会让新的 ListenStream 生效，
            # 必须先 daemon-reload 再重启 ssh.socket 本身
            systemctl daemon-reload 2>/dev/null
            systemctl restart ssh.socket 2>/dev/null || return 1
        fi
        systemctl restart ssh 2>/dev/null || systemctl restart sshd 2>/dev/null
    elif command -v rc-service &>/dev/null; then
        rc-service sshd restart 2>/dev/null || rc-service ssh restart 2>/dev/null
    elif command -v service &>/dev/null; then
        service ssh restart 2>/dev/null || service sshd restart 2>/dev/null
    else
        return 1
    fi
}

# 检测服务管理器并重启 fail2ban
restart_fail2ban() {
    if systemd_available; then
        systemctl restart fail2ban 2>/dev/null && return 0
    fi
    if command -v rc-service &>/dev/null; then
        rc-service fail2ban restart 2>/dev/null && return 0
    fi
    if command -v service &>/dev/null; then
        service fail2ban restart 2>/dev/null && return 0
    fi
    [ -x /etc/init.d/fail2ban ] && /etc/init.d/fail2ban restart 2>/dev/null
}

# 检测服务管理器并启动/停止 fail2ban
start_fail2ban() {
    # 确保 socket 目录存在（tmpfs 重启后会消失）
    mkdir -p /var/run/fail2ban 2>/dev/null
    chmod 755 /var/run/fail2ban 2>/dev/null

    # 写入 tmpfiles.d 确保重启后自动创建目录
    if command -v systemd-tmpfiles &>/dev/null; then
        echo "d /var/run/fail2ban 0755 root root -" > /etc/tmpfiles.d/fail2ban.conf 2>/dev/null
        systemd-tmpfiles --create /etc/tmpfiles.d/fail2ban.conf 2>/dev/null || true
    fi

    # 优先尝试 systemctl，失败则回退 service / rc-service
    if systemd_available; then
        systemctl start fail2ban 2>/dev/null && return 0
    fi
    if command -v rc-service &>/dev/null; then
        rc-service fail2ban start 2>/dev/null && return 0
    fi
    if command -v service &>/dev/null; then
        service fail2ban start 2>/dev/null && return 0
    fi
    # 最后回退：直接调用 init.d 脚本
    [ -x /etc/init.d/fail2ban ] && /etc/init.d/fail2ban start 2>/dev/null
}
stop_fail2ban() {
    if systemd_available; then
        systemctl stop fail2ban 2>/dev/null && return 0
    fi
    if command -v rc-service &>/dev/null; then
        rc-service fail2ban stop 2>/dev/null && return 0
    fi
    if command -v service &>/dev/null; then
        service fail2ban stop 2>/dev/null && return 0
    fi
    [ -x /etc/init.d/fail2ban ] && /etc/init.d/fail2ban stop 2>/dev/null
}

# ── 系统检测工具 ──────────────────────────────────────────

# 检测包管理器
pkg_install() {
    local PKG="$1"
    if command -v apt-get &>/dev/null; then
        apt-get update -qq 2>/dev/null
        apt-get install -y "$PKG" 2>/dev/null
    elif command -v apk &>/dev/null; then
        apk add --no-cache "$PKG" 2>/dev/null
    elif command -v yum &>/dev/null; then
        yum install -y "$PKG" 2>/dev/null
    elif command -v dnf &>/dev/null; then
        dnf install -y "$PKG" 2>/dev/null
    elif command -v pacman &>/dev/null; then
        pacman -Sy --noconfirm "$PKG" 2>/dev/null
    else
        return 1
    fi
}

pkg_remove() {
    local PKG="$1"
    if command -v apt-get &>/dev/null; then
        apt-get remove -y "$PKG" 2>/dev/null
    elif command -v apk &>/dev/null; then
        apk del "$PKG" 2>/dev/null
    elif command -v yum &>/dev/null; then
        yum remove -y "$PKG" 2>/dev/null
    elif command -v dnf &>/dev/null; then
        dnf remove -y "$PKG" 2>/dev/null
    else
        return 1
    fi
}

# 通用服务启用（开机自启）
svc_enable() {
    local SVC="$1"
    if systemd_available; then
        systemctl unmask "$SVC" 2>/dev/null || return 1
        systemctl enable "$SVC" --quiet 2>/dev/null
    elif command -v rc-update &>/dev/null; then
        rc-update add "$SVC" default 2>/dev/null
    elif command -v update-rc.d &>/dev/null; then
        update-rc.d "$SVC" enable 2>/dev/null
    else
        return 1
    fi
}

svc_disable() {
    local SVC="$1"
    if systemd_available; then
        systemctl disable "$SVC" --quiet 2>/dev/null
    elif command -v rc-update &>/dev/null; then
        rc-update del "$SVC" 2>/dev/null
    elif command -v update-rc.d &>/dev/null; then
        update-rc.d "$SVC" disable 2>/dev/null
    else
        return 1
    fi
}

# 通用服务 start/stop/restart 封装（systemd / OpenRC / sysvinit）
# OpenRC 服务名常带不同后缀，systemd 用 .service；调用方传裸名即可。
# 获取默认出口网卡：ip route get 比 awk '/^default/' 更准
# （多默认路由 / 策略路由 / IPv6-only 时不易取错），失败回退旧法
default_iface() {
    local DEV
    DEV=$(ip route get 1.1.1.1 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev"){print $(i+1); exit}}')
    [ -z "$DEV" ] && DEV=$(ip -6 route get 2606:4700:4700::1111 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev"){print $(i+1); exit}}')
    [ -z "$DEV" ] && DEV=$(ip route 2>/dev/null | awk '/^default/{print $5; exit}')
    echo "$DEV"
}

svc_start() {
    local SVC="$1"
    if systemd_available; then
        systemctl start "$SVC" 2>/dev/null
    elif command -v rc-service &>/dev/null; then
        rc-service "$SVC" start 2>/dev/null
    elif command -v service &>/dev/null; then
        service "$SVC" start 2>/dev/null
    else
        return 1
    fi
}

svc_stop() {
    local SVC="$1"
    if systemd_available; then
        systemctl stop "$SVC" 2>/dev/null
    elif command -v rc-service &>/dev/null; then
        rc-service "$SVC" stop 2>/dev/null
    elif command -v service &>/dev/null; then
        service "$SVC" stop 2>/dev/null
    else
        return 1
    fi
}

svc_restart() {
    local SVC="$1"
    if systemd_available; then
        systemctl restart "$SVC" 2>/dev/null
    elif command -v rc-service &>/dev/null; then
        rc-service "$SVC" restart 2>/dev/null
    elif command -v service &>/dev/null; then
        service "$SVC" restart 2>/dev/null
    else
        return 1
    fi
}

# 通用服务 is-active 检测
svc_is_active() {
    local SVC="$1"
    if systemd_available; then
        systemctl is-active --quiet "$SVC" 2>/dev/null
    elif command -v rc-service &>/dev/null; then
        rc-service "$SVC" status &>/dev/null
    elif command -v service &>/dev/null; then
        service "$SVC" status &>/dev/null
    else
        return 1
    fi
}

# systemctl daemon-reload 兼容（OpenRC 不需要）
svc_daemon_reload() {
    command -v systemctl &>/dev/null && systemctl daemon-reload 2>/dev/null || true
}

# 获取 OS codename（兼容无 lsb_release 的系统）
get_codename() {
    if command -v lsb_release &>/dev/null; then
        lsb_release -cs 2>/dev/null
    elif [ -f /etc/os-release ]; then
        grep VERSION_CODENAME /etc/os-release | cut -d= -f2 | tr -d '"'
    elif [ -f /etc/debian_version ]; then
        cat /etc/debian_version | cut -d. -f1
    else
        echo "unknown"
    fi
}

# ── 权限检查与提权引导 ────────────────────────────────────
VPS_TOOLS_INSTALL_URL="https://raw.githubusercontent.com/TonyJsonson-8748/SSH-Hardening/refs/heads/main/SSH-Hardening.sh"

vps_tools_elevation_help() {
    local ELEVATOR="${1:-sudo}"
    echo ""
    echo "本脚本会修改系统用户、SSH、防火墙和服务配置，必须使用 root 权限。"
    if [ "$ELEVATOR" = "doas" ]; then
        echo "通过网络运行：doas bash -c 'bash <(curl -fsSL $VPS_TOOLS_INSTALL_URL)'"
        echo "已安装后运行：doas v"
    else
        echo "通过网络运行：sudo bash -c 'bash <(curl -fsSL $VPS_TOOLS_INSTALL_URL)'"
        echo "已安装后运行：sudo v"
    fi
    echo "没有 sudo/doas 时：先执行 su - 切换到 root，再重新运行。"
}

vps_tools_require_root_or_elevate() {
    local ELEVATOR="" ANSWER="" CURRENT_USER SSH_CONTEXT="" SSH_FAMILY=""
    [ "$EUID" -eq 0 ] && return 0
    CURRENT_USER=$(id -un 2>/dev/null || echo "UID $EUID")
    echo -e "${RED}[ERROR]${NC} 当前用户 ${CURRENT_USER} 不是 root。"

    if command -v sudo >/dev/null 2>&1; then
        ELEVATOR=sudo
    elif command -v doas >/dev/null 2>&1; then
        ELEVATOR=doas
    fi

    case "$0" in
        /dev/fd/*|/proc/*/fd/*)
            vps_tools_elevation_help "${ELEVATOR:-sudo}"
            echo "当前使用 bash <(curl ...) 运行，文件描述符不能安全传给提权进程，请复制上面的命令重试。"
            return 1
            ;;
    esac

    if [ -z "$ELEVATOR" ]; then
        vps_tools_elevation_help sudo
        echo "当前系统未检测到 sudo 或 doas，请联系管理员授予权限。"
        return 1
    fi
    if [ ! -t 0 ]; then
        vps_tools_elevation_help "$ELEVATOR"
        echo "当前不是交互终端，无法安全询问提权密码。"
        return 1
    fi

    read -rp "  是否使用 ${ELEVATOR} 以 root 权限重新运行？(Y/n): " ANSWER
    [ -z "$ANSWER" ] && ANSWER=y
    echo "$ANSWER" | grep -qiE '^y(es)?$' || {
        vps_tools_elevation_help "$ELEVATOR"
        return 1
    }

    SSH_CONTEXT=$(vps_tools_ssh_connection 2>/dev/null || true)
    SSH_FAMILY=$(vps_tools_ssh_family 2>/dev/null || true)
    if [ "$ELEVATOR" = sudo ]; then
        if sudo -v; then
            exec sudo env \
                VPS_TOOLS_SSH_CONNECTION="$SSH_CONTEXT" \
                VPS_TOOLS_SSH_FAMILY="$SSH_FAMILY" \
                bash "$0" "$@"
        fi
    elif doas true; then
        exec doas env \
            VPS_TOOLS_SSH_CONNECTION="$SSH_CONTEXT" \
            VPS_TOOLS_SSH_FAMILY="$SSH_FAMILY" \
            bash "$0" "$@"
    fi
    echo -e "${RED}[ERROR]${NC} ${ELEVATOR} 提权失败，当前账号可能没有管理员权限。"
    vps_tools_elevation_help "$ELEVATOR"
    return 1
}

if [ "$EUID" -ne 0 ] && [ "${VPS_TOOLS_TEST_MODE:-0}" != "1" ] && [ "${1:-}" != "--help" ] && [ "${1:-}" != "-h" ] && [ "${1:-}" != "help" ]; then
    vps_tools_require_root_or_elevate "$@" || exit 1
fi

# ── 通用工具函数 ──────────────────────────────────────────
sshd_effective_value() {
    local KEY="$1" WANT VALUE
    command -v sshd >/dev/null 2>&1 || return 1
    WANT=$(printf '%s' "$KEY" | tr '[:upper:]' '[:lower:]')
    VALUE=$(sshd -T 2>/dev/null | awk -v k="$WANT" \
        'tolower($1) == tolower(k) {print $2; exit}')
    [ -n "$VALUE" ] || return 1
    printf '%s\n' "$VALUE"
}

get_config() {
    local VALUE
    VALUE=$(sshd_effective_value "$1" 2>/dev/null || true)
    [ -n "$VALUE" ] && { printf '%s\n' "$VALUE"; return 0; }
    awk -v key="$1" '
        tolower($1) == tolower(key) {value=$2}
        END {if (value != "") print value}
    ' "$SSHD_CONFIG" 2>/dev/null
}

ssh_key_count() {
    local COUNT
    COUNT=$(grep -cE '^(ssh-rsa|ssh-ed25519|ecdsa-sha2|sk-ssh|sk-ecdsa|ssh-dss) ' "$AUTH_KEYS" 2>/dev/null || true)
    case "$COUNT" in
        ''|*[!0-9]*) printf '0\n' ;;
        *) printf '%s\n' "$COUNT" ;;
    esac
}

set_config_file() {
    local FILE="$1" KEY="$2" VALUE="$3"
    local BODY="" BLOCK="" TMP="" KEY_LOWER
    if [ -e "$FILE" ] || [ -L "$FILE" ]; then
        [ -f "$FILE" ] && [ ! -L "$FILE" ] || return 1
    else
        : > "$FILE" || return 1
    fi
    BODY=$(mktemp) || return 1
    BLOCK=$(mktemp) || { rm -f "$BODY"; return 1; }
    TMP=$(mktemp "${FILE}.vps-tools.XXXXXX") || {
        rm -f "$BODY" "$BLOCK"
        return 1
    }
    if ! cp -a -- "$FILE" "$TMP"; then
        rm -f "$BODY" "$BLOCK" "$TMP"
        return 1
    fi
    KEY_LOWER=$(printf '%s' "$KEY" | tr '[:upper:]' '[:lower:]') || {
        rm -f "$BODY" "$BLOCK" "$TMP"
        return 1
    }

    if ! awk -v begin="$SSHD_MANAGED_BEGIN" -v end="$SSHD_MANAGED_END" \
        -v key_lower="$KEY_LOWER" '
        function first_field(line, fields) {
            sub(/^[[:space:]]+/, "", line)
            split(line, fields, /[[:space:]]+/)
            return tolower(fields[1])
        }
        $0 == begin {in_block=1; next}
        $0 == end {in_block=0; next}
        in_block {next}
        {
            field=first_field($0)
            if (field == "match") in_match=1
            # Port is additive in sshd_config. Remove active, unmanaged,
            # global Port directives so changing the managed value cannot
            # silently leave the old listener enabled.
            if (key_lower == "port" && !in_match && field == "port") next
            print
        }
    ' "$FILE" > "$BODY"; then
        rm -f "$BODY" "$BLOCK" "$TMP"
        return 1
    fi

    if ! awk -v begin="$SSHD_MANAGED_BEGIN" -v end="$SSHD_MANAGED_END" -v key="$KEY" '
        $0 == begin {in_block=1; next}
        $0 == end {in_block=0; next}
        in_block {
            line=$0
            sub(/^[[:space:]]+/, "", line)
            split(line, fields, /[[:space:]]+/)
            if (line != "" && tolower(fields[1]) != tolower(key)) print line
        }
    ' "$FILE" > "$BLOCK"; then
        rm -f "$BODY" "$BLOCK" "$TMP"
        return 1
    fi

    if ! {
        printf '%s\n' "$SSHD_MANAGED_BEGIN" \
            && cat "$BLOCK" \
            && printf '%s\n' "${KEY} ${VALUE}" \
            && printf '%s\n\n' "$SSHD_MANAGED_END" \
            && cat "$BODY"
    } > "$TMP"; then
        rm -f "$BODY" "$BLOCK" "$TMP"
        return 1
    fi
    if ! mv -f -- "$TMP" "$FILE"; then
        rm -f "$BODY" "$BLOCK" "$TMP"
        return 1
    fi
    rm -f "$BODY" "$BLOCK" || true
    return 0
}

set_config() {
    set_config_file "$SSHD_CONFIG" "$1" "$2"
}

backup_config() {
    local BACKUP CURRENT_STATE BACKUP_DIGEST BACKUP_STATE
    [ -f "$SSHD_CONFIG" ] && [ ! -L "$SSHD_CONFIG" ] || {
        error "SSH 配置必须是普通文件，拒绝修改符号链接或特殊文件：$SSHD_CONFIG"
        return 1
    }
    if command -v ssh_config_file_state >/dev/null 2>&1; then
        CURRENT_STATE=$(ssh_config_file_state "$SSHD_CONFIG") || {
            error "无法稳定读取 SSH 配置，拒绝创建可能不一致的备份"
            return 1
        }
        if [ -n "${SSH_CONFIG_PREPARED_STATE:-}" ] \
            && [ "$CURRENT_STATE" != "$SSH_CONFIG_PREPARED_STATE" ]; then
            error "候选配置准备后 sshd_config 已发生变化，请重新操作"
            return 1
        fi
    fi
    BACKUP="$SSHD_CONFIG.bak.$(date +%Y%m%d_%H%M%S)_$$_${RANDOM}"
    if ! cp -a -- "$SSHD_CONFIG" "$BACKUP" \
        || ! cmp -s "$SSHD_CONFIG" "$BACKUP"; then
        rm -f "$BACKUP"
        error "无法备份 SSH 配置：$SSHD_CONFIG"
        return 1
    fi
    BACKUP_DIGEST=$(cksum < "$BACKUP" 2>/dev/null) || {
        rm -f -- "$BACKUP"
        error "无法校验 SSH 配置备份"
        return 1
    }
    if command -v ssh_config_file_state >/dev/null 2>&1; then
        BACKUP_STATE=$(ssh_config_file_state "$BACKUP") || {
            rm -f -- "$BACKUP"
            error "无法稳定记录 SSH 配置备份状态"
            return 1
        }
    fi
    LAST_SSHD_BACKUP="$BACKUP"   # 供 apply_and_restart 失败时回滚
    LAST_SSHD_BACKUP_DIGEST="$BACKUP_DIGEST"
    LAST_SSHD_BACKUP_STATE="$BACKUP_STATE"
    if command -v ssh_socket_override_backup >/dev/null 2>&1 \
        && ! ssh_socket_override_backup; then
        rm -f -- "$BACKUP"
        error "无法备份 SSH socket 端口覆盖文件：$SSHD_SOCKET_OVERRIDE_FILE"
        return 1
    fi
    info "配置已备份：$BACKUP"
}

ssh_config_file_restore_state() {
    local FILE="$1" BEFORE_META AFTER_META DIGEST
    [ -f "$FILE" ] && [ ! -L "$FILE" ] || return 1
    BEFORE_META=$(stat -Lc '%u:%g:%a:%s:%Y:%F' -- "$FILE" 2>/dev/null) \
        || return 1
    DIGEST=$(cksum < "$FILE" 2>/dev/null) || return 1
    AFTER_META=$(stat -Lc '%u:%g:%a:%s:%Y:%F' -- "$FILE" 2>/dev/null) \
        || return 1
    [ "$AFTER_META" = "$BEFORE_META" ] || return 1
    printf '%s|%s\n' "$BEFORE_META" "$DIGEST"
}

# shellcheck disable=SC2120  # BACKUP falls back to LAST_SSHD_BACKUP; kept callable with an explicit path
restore_ssh_config_backup() {
    local BACKUP="${1:-${LAST_SSHD_BACKUP:-}}" RESTORE_TMP=""
    local BACKUP_DIGEST CURRENT_DIGEST CURRENT_STATE SECOND_STATE
    local BACKUP_STATE CURRENT_RESTORE_STATE BACKUP_RESTORE_STATE NEEDS_RESTORE=no
    [ -n "$BACKUP" ] && [ -f "$BACKUP" ] && [ ! -L "$BACKUP" ] || {
        error "未找到可回滚的 SSH 配置备份"
        return 1
    }
    [ -f "$SSHD_CONFIG" ] && [ ! -L "$SSHD_CONFIG" ] || {
        error "SSH 配置目标不再是安全的普通文件，拒绝覆盖：$SSHD_CONFIG"
        return 1
    }
    BACKUP_DIGEST=$(cksum < "$BACKUP" 2>/dev/null) || return 1
    if [ "$BACKUP" = "${LAST_SSHD_BACKUP:-}" ]; then
        if [ -z "${LAST_SSHD_BACKUP_DIGEST:-}" ] \
            || [ "$BACKUP_DIGEST" != "$LAST_SSHD_BACKUP_DIGEST" ]; then
            error "SSH 配置备份内容已在创建后发生变化，拒绝用于回滚"
            return 1
        fi
        if [ -n "${LAST_SSHD_BACKUP_STATE:-}" ] \
            && command -v ssh_config_file_state >/dev/null 2>&1; then
            BACKUP_STATE=$(ssh_config_file_state "$BACKUP") || return 1
            if [ "$BACKUP_STATE" != "$LAST_SSHD_BACKUP_STATE" ]; then
                error "SSH 配置备份元数据已在创建后发生变化，拒绝用于回滚"
                return 1
            fi
        fi
    fi
    CURRENT_DIGEST=$(cksum < "$SSHD_CONFIG" 2>/dev/null) || return 1
    BACKUP_RESTORE_STATE=$(ssh_config_file_restore_state "$BACKUP") || return 1
    CURRENT_RESTORE_STATE=$(ssh_config_file_restore_state "$SSHD_CONFIG") || return 1
    [ "$CURRENT_RESTORE_STATE" = "$BACKUP_RESTORE_STATE" ] || NEEDS_RESTORE=yes
    if [ "$NEEDS_RESTORE" = yes ]; then
        if command -v ssh_config_file_state >/dev/null 2>&1; then
            CURRENT_STATE=$(ssh_config_file_state "$SSHD_CONFIG") || return 1
            if [ -z "${SSH_CONFIG_APPLIED_DIGEST:-}" ] \
                || [ -z "${SSH_CONFIG_APPLIED_STATE:-}" ] \
                || [ "$CURRENT_DIGEST" != "$SSH_CONFIG_APPLIED_DIGEST" ] \
                || [ "$CURRENT_STATE" != "$SSH_CONFIG_APPLIED_STATE" ]; then
                error "sshd_config 在回滚前出现并发修改，拒绝用旧备份覆盖"
                return 1
            fi
        fi
        RESTORE_TMP=$(mktemp "${SSHD_CONFIG}.vps-tools-restore.XXXXXX") || return 1
        if ! cp -a -- "$BACKUP" "$RESTORE_TMP" \
            || ! cmp -s "$BACKUP" "$RESTORE_TMP"; then
            rm -f -- "$RESTORE_TMP"
            error "无法准备原子 SSH 配置恢复文件：$BACKUP"
            return 1
        fi
        if command -v ssh_config_file_state >/dev/null 2>&1; then
            SECOND_STATE=$(ssh_config_file_state "$SSHD_CONFIG") || SECOND_STATE=""
            if [ "$SECOND_STATE" != "$CURRENT_STATE" ]; then
                rm -f -- "$RESTORE_TMP"
                error "SSH 配置在恢复提交前再次发生变化，拒绝覆盖"
                return 1
            fi
        fi
        if ! mv -f -- "$RESTORE_TMP" "$SSHD_CONFIG" 2>/dev/null; then
            rm -f -- "$RESTORE_TMP"
            error "无法原子恢复 sshd_config，请立即手动处理：$BACKUP"
            return 1
        fi
    fi
    CURRENT_RESTORE_STATE=$(ssh_config_file_restore_state "$SSHD_CONFIG") || return 1
    if [ "$CURRENT_RESTORE_STATE" != "$BACKUP_RESTORE_STATE" ]; then
        error "无法从备份恢复 sshd_config，请立即手动处理：$BACKUP"
        return 1
    fi
    warn "已回滚 sshd_config 到备份：$BACKUP"
    if command -v ssh_socket_override_restore >/dev/null 2>&1 \
        && ! ssh_socket_override_restore; then
        error "无法回滚 SSH socket 端口覆盖文件，请立即手动检查：$SSHD_SOCKET_OVERRIDE_FILE"
        return 1
    fi
    if sshd -t 2>/dev/null && restart_ssh; then
        info "已用备份配置恢复 SSH 服务 ✓"
        return 0
    fi
    error "配置已恢复，但 SSH 服务仍异常，请立即手动检查！"
    return 1
}

apply_and_restart() {
    if ! sshd -t 2>/dev/null; then
        error "配置文件语法错误，自动回滚中..."
        restore_ssh_config_backup && return 1
        return 2
    fi
    if restart_ssh; then
        info "SSH 服务已重启 ✓"
    else
        error "SSH 服务重启失败，自动回滚中..."
        restore_ssh_config_backup && return 1
        return 2
    fi
}

list_keys() {
    if [ ! -f "$AUTH_KEYS" ] || ! grep -qE '^(ssh-rsa|ssh-ed25519|ecdsa-sha2|sk-ssh|sk-ecdsa|ssh-dss) ' "$AUTH_KEYS" 2>/dev/null; then
        echo -e "  ${YELLOW}（暂无公钥）${NC}"
        return 1
    fi
    local i=1
    while IFS= read -r line; do
        if echo "$line" | grep -qE '^(ssh-rsa|ssh-ed25519|ecdsa-sha2|sk-ssh|sk-ecdsa|ssh-dss) '; then
            local TYPE COMMENT FINGER
            TYPE=$(echo "$line" | awk '{print $1}')
            COMMENT=$(echo "$line" | awk '{print $3}')
            FINGER=$(echo "$line" | ssh-keygen -lf /dev/stdin 2>/dev/null | awk '{print $2}' || echo "N/A")
            echo -e "  ${GREEN}[$i]${NC} ${BOLD}$TYPE${NC}"
            echo -e "      ${DIM}指纹：${NC}${BLUE}$FINGER${NC}"
            echo -e "      ${DIM}备注：${NC}${YELLOW}${COMMENT:-（无备注）}${NC}"
            echo ""
            i=$((i+1))
        fi
    done < "$AUTH_KEYS"
    return 0
}

firewall_iptables_persistence_available() {
    local RULES_FILE="$1"
    [ "${VPS_TOOLS_TEST_MODE:-0}" = 1 ] && return 0
    case "$RULES_FILE" in
        /etc/iptables/rules.v4|/etc/iptables/rules.v6) ;;
        *) return 1 ;;
    esac
    command -v systemctl >/dev/null 2>&1 || return 1
    systemctl is-enabled --quiet netfilter-persistent.service >/dev/null 2>&1
}

firewall_iptables_save_rules() {
    local RULES_FILE="$1" SAVE_TMP SAVE_COMMAND=""
    case "$RULES_FILE" in
        *.v6) SAVE_COMMAND=ip6tables-save ;;
        *.v4) SAVE_COMMAND=iptables-save ;;
        *) SAVE_COMMAND="${FIREWALL_NETFILTER_SAVE_CMD:-iptables-save}" ;;
    esac
    command -v "$SAVE_COMMAND" >/dev/null 2>&1 || return 1
    firewall_iptables_persistence_available "$RULES_FILE" || return 1
    [ -f "$RULES_FILE" ] && [ ! -L "$RULES_FILE" ] || return 1
    SAVE_TMP=$(mktemp "${RULES_FILE}.vps-tools.XXXXXX") || return 1
    if ! cp -a -- "$RULES_FILE" "$SAVE_TMP" \
        || ! "$SAVE_COMMAND" > "$SAVE_TMP" \
        || ! mv -f -- "$SAVE_TMP" "$RULES_FILE"; then
        rm -f -- "$SAVE_TMP"
        return 1
    fi
}

firewall_ufw_port_state() {
    local STATUS="$1" PORT="$2"
    printf '%s\n' "$STATUS" | LC_ALL=C awk -v port="${PORT}/tcp" '
        {
            port_index=0
            for (i=1; i<=NF; i++) if ($i == port) {port_index=i; break}
            if (!port_index) next
            action=""
            action_index=0
            scoped=(port_index > 1)
            for (i=port_index+1; i<=NF; i++) {
                if ($i == "on") scoped=1
                if ($i == "ALLOW" || $i == "DENY" || $i == "REJECT" \
                    || $i == "LIMIT") {
                    action=$i
                    action_index=i
                    break
                }
            }
            if (!action_index) next
            direction=""
            source_index=action_index + 1
            if ($(source_index) == "IN" || $(source_index) == "OUT" \
                || $(source_index) == "FWD") {
                direction=$(source_index)
                source_index++
            }
            source=$(source_index)
            inbound=(direction == "" || direction == "IN")
            if (inbound && (action == "DENY" || action == "REJECT")) denied=1
            if (inbound && (action == "ALLOW" || action == "LIMIT") \
                && (scoped || source != "Anywhere")) policy=1
            if (inbound && !scoped && action == "ALLOW" \
                && source == "Anywhere") allowed=1
            if (inbound && !scoped && action == "LIMIT" \
                && source == "Anywhere") limited=1
        }
        END {
            if (denied) print "deny"
            else if (policy) print "policy"
            else if (allowed && limited) print "allow-limit"
            else if (allowed) print "allow"
            else if (limited) print "limit"
            else print "missing"
        }
    '
}

firewall_ufw_allow_count() {
    local STATUS="$1" PORT="$2"
    printf '%s\n' "$STATUS" | LC_ALL=C awk -v port="${PORT}/tcp" '
        {
            port_index=0
            for (i=1; i<=NF; i++) if ($i == port) {port_index=i; break}
            if (!port_index) next
            action=""
            action_index=0
            scoped=0
            for (i=port_index+1; i<=NF; i++) {
                if ($i == "on") scoped=1
                if ($i == "ALLOW" || $i == "LIMIT") {
                    action=$i
                    action_index=i
                    break
                }
                if ($i == "DENY" || $i == "REJECT") break
            }
            if (!action_index) next
            direction=""
            source_index=action_index + 1
            if ($(source_index) == "IN" || $(source_index) == "OUT" \
                || $(source_index) == "FWD") {
                direction=$(source_index)
                source_index++
            }
            if ((direction == "" || direction == "IN") && !scoped \
                && (action == "ALLOW" || action == "LIMIT") \
                && $(source_index) == "Anywhere") count++
        }
        END {print count+0}
    '
}

firewall_firewalld_ssh_zone() {
    local CLIENT_IP="" ROUTE="" IFACE="" ZONE="" ACTIVE_ZONES=""
    local SOURCE_ZONE="" PERMANENT_SOURCE_ZONE=""
    if [ -n "${FIREWALL_TEST_ZONE:-}" ] && [ "${VPS_TOOLS_TEST_MODE:-0}" = 1 ]; then
        printf '%s\n' "$FIREWALL_TEST_ZONE"
        return 0
    fi
    ACTIVE_ZONES=$(LC_ALL=C firewall-cmd --get-active-zones 2>/dev/null) || return 1
    CLIENT_IP=$(vps_tools_ssh_client_ip 2>/dev/null || true)
    if [ -n "$CLIENT_IP" ]; then
        if SOURCE_ZONE=$(LC_ALL=C firewall-cmd \
            --get-zone-of-source="$CLIENT_IP" 2>/dev/null); then
            case "$SOURCE_ZONE" in ""|"no zone") SOURCE_ZONE="" ;; esac
        else
            SOURCE_ZONE=""
        fi
        if PERMANENT_SOURCE_ZONE=$(LC_ALL=C firewall-cmd --permanent \
            --get-zone-of-source="$CLIENT_IP" 2>/dev/null); then
            case "$PERMANENT_SOURCE_ZONE" in
                ""|"no zone") PERMANENT_SOURCE_ZONE="" ;;
            esac
        else
            PERMANENT_SOURCE_ZONE=""
        fi
        if [ -n "$SOURCE_ZONE" ]; then
            [[ "$SOURCE_ZONE" =~ ^[A-Za-z0-9_-]+$ ]] || return 1
            [ "$PERMANENT_SOURCE_ZONE" = "$SOURCE_ZONE" ] || return 1
            printf '%s\n' "$SOURCE_ZONE"
            return 0
        fi
        # A permanent-only source binding means the runtime and next reload
        # would route this client through different zones.
        [ -z "$PERMANENT_SOURCE_ZONE" ] || return 1
        if printf '%s\n' "$ACTIVE_ZONES" \
            | grep -q '^[[:space:]]*sources:[[:space:]]'; then
            return 1
        fi
    fi
    if [ -n "$CLIENT_IP" ] && command -v ip >/dev/null 2>&1; then
        ROUTE=$(LC_ALL=C ip route get "$CLIENT_IP" 2>/dev/null) || return 1
        IFACE=$(printf '%s\n' "$ROUTE" | awk '
            {
                for (i=1; i<NF; i++) if ($i == "dev") {print $(i+1); exit}
            }
        ')
    fi
    if [ -n "$IFACE" ]; then
        ZONE=$(LC_ALL=C firewall-cmd --get-zone-of-interface="$IFACE" 2>/dev/null) \
            || return 1
        case "$ZONE" in
            ""|"no zone")
                ZONE=$(LC_ALL=C firewall-cmd --get-default-zone 2>/dev/null) || return 1
                ;;
        esac
    else
        ZONE=$(printf '%s\n' "$ACTIVE_ZONES" \
            | awk '/^[^[:space:]]/ {zone=$1; count++} END {if (count == 1) print zone}')
    fi
    [[ "$ZONE" =~ ^[A-Za-z0-9_-]+$ ]] || return 1
    printf '%s\n' "$ZONE"
}

firewall_detect_backend() {
    local FIREWALLD_STATE="" NFT_RULESET="" CLIENT_ADDR="" CLIENT_FAMILY=""
    local NFT_NATIVE_ACTIVE=no
    FIREWALL_BACKEND=none
    FIREWALL_UFW_STATUS=""
    FIREWALL_IPTABLES_V4_RULES=""
    FIREWALL_IPTABLES_V6_RULES=""
    FIREWALL_IPTABLES_V4_ACTIVE=no
    FIREWALL_IPTABLES_V6_ACTIVE=no
    FIREWALL_FIREWALLD_ZONE=""
    FIREWALL_NETFILTER_CMD=iptables
    FIREWALL_NETFILTER_SAVE_CMD=iptables-save
    FIREWALL_NETFILTER_RULES_DEFAULT=/etc/iptables/rules.v4
    CLIENT_ADDR=$(vps_tools_ssh_client_ip 2>/dev/null || true)
    CLIENT_FAMILY=$(vps_tools_ssh_family 2>/dev/null || true)
    if [ "$CLIENT_FAMILY" = 6 ]; then
        FIREWALL_NETFILTER_CMD=ip6tables
        FIREWALL_NETFILTER_SAVE_CMD=ip6tables-save
        FIREWALL_NETFILTER_RULES_DEFAULT=/etc/iptables/rules.v6
    fi

    if command -v ufw >/dev/null 2>&1; then
        FIREWALL_UFW_STATUS=$(LC_ALL=C ufw status 2>/dev/null) || {
            error "无法可靠读取 UFW 状态，拒绝继续修改 SSH 端口"
            return 1
        }
        case "$FIREWALL_UFW_STATUS" in
            *"Status: active"*)
                FIREWALL_BACKEND=ufw
                return 0
                ;;
            *"Status: inactive"*) ;;
            *)
                error "UFW 返回未知状态，拒绝继续修改 SSH 端口"
                return 1
                ;;
        esac
    fi

    if command -v firewall-cmd >/dev/null 2>&1; then
        if svc_is_active firewalld; then
            FIREWALLD_STATE=active
        elif command -v systemctl >/dev/null 2>&1; then
            FIREWALLD_STATE=$(LC_ALL=C systemctl is-active firewalld.service 2>/dev/null) \
                || true
            case "$FIREWALLD_STATE" in
                inactive|failed|unknown) FIREWALLD_STATE=inactive ;;
                active) ;;
                *)
                    error "无法可靠读取 firewalld 状态，拒绝继续修改 SSH 端口"
                    return 1
                    ;;
            esac
        elif LC_ALL=C firewall-cmd --state >/dev/null 2>&1; then
            FIREWALLD_STATE=active
        else
            error "无法可靠确认 firewalld 是否活跃，拒绝继续修改 SSH 端口"
            return 1
        fi
        if [ "$FIREWALLD_STATE" = active ]; then
            FIREWALL_FIREWALLD_ZONE=$(firewall_firewalld_ssh_zone) || {
                error "无法定位 SSH 入站接口对应的 firewalld zone，拒绝修改错误的 zone"
                return 1
            }
            FIREWALL_BACKEND=firewalld
            return 0
        fi
    fi

    if command -v iptables >/dev/null 2>&1; then
        FIREWALL_IPTABLES_V4_RULES=$(iptables -S INPUT 2>/dev/null) || {
            error "无法可靠读取 iptables INPUT 状态，拒绝继续修改 SSH 端口"
            return 1
        }
        if printf '%s\n' "$FIREWALL_IPTABLES_V4_RULES" | awk '
            $1 == "-P" && $2 == "INPUT" && $3 != "ACCEPT" {active=1}
            $1 == "-A" && $2 == "INPUT" {active=1}
            END {exit !active}
        '; then
            FIREWALL_IPTABLES_V4_ACTIVE=yes
        fi
    fi
    if command -v ip6tables >/dev/null 2>&1; then
        FIREWALL_IPTABLES_V6_RULES=$(ip6tables -S INPUT 2>/dev/null) || {
            error "无法可靠读取 ip6tables INPUT 状态，拒绝继续修改 SSH 端口"
            return 1
        }
        if printf '%s\n' "$FIREWALL_IPTABLES_V6_RULES" | awk '
            $1 == "-P" && $2 == "INPUT" && $3 != "ACCEPT" {active=1}
            $1 == "-A" && $2 == "INPUT" {active=1}
            END {exit !active}
        '; then
            FIREWALL_IPTABLES_V6_ACTIVE=yes
        fi
    fi
    if command -v nft >/dev/null 2>&1; then
        NFT_RULESET=$(LC_ALL=C nft list ruleset 2>/dev/null) || {
            error "无法可靠读取原生 nftables 状态，拒绝继续修改 SSH 端口"
            return 1
        }
        if printf '%s\n' "$NFT_RULESET" | awk \
            -v iptables_v4="$FIREWALL_IPTABLES_V4_ACTIVE" \
            -v iptables_v6="$FIREWALL_IPTABLES_V6_ACTIVE" '
            function chain_is_independent() {
                if (table_family == "inet") return 1
                if (table_family == "ip" && iptables_v4 == "yes" \
                    && table_name == "filter" && chain_name == "INPUT") return 0
                if (table_family == "ip6" && iptables_v6 == "yes" \
                    && table_name == "filter" && chain_name == "INPUT") return 0
                return table_family == "ip" || table_family == "ip6"
            }
            {
                line=$0
                if ($1 == "table") {
                    table_family=$2
                    table_name=$3
                    gsub(/[{};]/, "", table_name)
                }
                if ($1 == "chain") {
                    in_chain=1
                    chain_base_depth=depth
                    chain_name=$2
                    gsub(/[{};]/, "", chain_name)
                    has_input_hook=0
                }
                if (in_chain) {
                    if (line ~ /hook[[:space:]]+input/) has_input_hook=1
                }
                brace_line=line
                opens=gsub(/{/, "{", brace_line)
                brace_line=line
                closes=gsub(/}/, "}", brace_line)
                depth += opens - closes
                if (in_chain && depth <= chain_base_depth) {
                    if (has_input_hook && chain_is_independent()) found=1
                    in_chain=0
                }
            }
            END {exit !found}
        '; then
            NFT_NATIVE_ACTIVE=yes
        fi
    fi
    if { [ "$FIREWALL_IPTABLES_V4_ACTIVE" = yes ] \
            || [ "$FIREWALL_IPTABLES_V6_ACTIVE" = yes ]; } \
        && [ "$NFT_NATIVE_ACTIVE" = yes ]; then
        error "检测到 iptables 与独立 nftables INPUT 规则同时生效，无法安全选择唯一防火墙后端"
        return 1
    fi
    if [ "$FIREWALL_IPTABLES_V4_ACTIVE" = yes ] \
        || [ "$FIREWALL_IPTABLES_V6_ACTIVE" = yes ]; then
        FIREWALL_BACKEND=iptables
    elif [ "$NFT_NATIVE_ACTIVE" = yes ]; then
        FIREWALL_BACKEND=nft-unsupported
    fi
    return 0
}

firewall_rollback_allowed_port() {
    local PORT="$1" FAILED=no
    local NETFILTER_CMD="${FIREWALL_ALLOW_NETFILTER_CMD:-iptables}"
    FIREWALL_ALLOW_DIRTY=yes

    if [ "${FIREWALL_ALLOW_UFW_ADDED:-no}" = yes ]; then
        if ufw delete allow "${PORT}/tcp" >/dev/null 2>&1; then
            FIREWALL_ALLOW_UFW_ADDED=no
        else
            FAILED=yes
            warn "回滚本次新增的 ufw ${PORT}/tcp 规则失败"
        fi
    fi
    if [ "${FIREWALL_ALLOW_FIREWALLD_RUNTIME_ADDED:-no}" = yes ]; then
        if firewall-cmd --zone="${FIREWALL_ALLOW_FIREWALLD_ZONE}" \
            --remove-port="${PORT}/tcp" >/dev/null 2>&1; then
            FIREWALL_ALLOW_FIREWALLD_RUNTIME_ADDED=no
        else
            FAILED=yes
            warn "回滚本次新增的 firewalld 运行时 ${PORT}/tcp 规则失败"
        fi
    fi
    if [ "${FIREWALL_ALLOW_FIREWALLD_PERMANENT_ADDED:-no}" = yes ]; then
        if firewall-cmd --permanent --zone="${FIREWALL_ALLOW_FIREWALLD_ZONE}" \
            --remove-port="${PORT}/tcp" >/dev/null 2>&1; then
            FIREWALL_ALLOW_FIREWALLD_PERMANENT_ADDED=no
        else
            FAILED=yes
            warn "回滚本次新增的 firewalld 永久 ${PORT}/tcp 规则失败"
        fi
    fi
    if [ "${FIREWALL_ALLOW_IPTABLES_V4_ADDED:-no}" = yes ]; then
        if iptables -D INPUT -p tcp --dport "$PORT" -j ACCEPT \
            >/dev/null 2>&1; then
            if firewall_iptables_save_rules \
                "${FIREWALL_ALLOW_IPTABLES_V4_RULES_FILE:-/etc/iptables/rules.v4}"; then
                FIREWALL_ALLOW_IPTABLES_V4_ADDED=no
            else
                FAILED=yes
                warn "iptables 新端口规则已回滚，但 IPv4 持久化保存失败"
            fi
        else
            FAILED=yes
            warn "回滚本次新增的 iptables ${PORT}/tcp 规则失败"
        fi
    fi
    if [ "${FIREWALL_ALLOW_IPTABLES_V6_ADDED:-no}" = yes ]; then
        if ip6tables -D INPUT -p tcp --dport "$PORT" -j ACCEPT \
            >/dev/null 2>&1; then
            if firewall_iptables_save_rules \
                "${FIREWALL_ALLOW_IPTABLES_V6_RULES_FILE:-/etc/iptables/rules.v6}"; then
                FIREWALL_ALLOW_IPTABLES_V6_ADDED=no
            else
                FAILED=yes
                warn "ip6tables 新端口规则已回滚，但 IPv6 持久化保存失败"
            fi
        else
            FAILED=yes
            warn "回滚本次新增的 ip6tables ${PORT}/tcp 规则失败"
        fi
    fi
    if [ "${FIREWALL_ALLOW_IPTABLES_V4_ADDED:-no}" = no ] \
        && [ "${FIREWALL_ALLOW_IPTABLES_V6_ADDED:-no}" = no ]; then
        FIREWALL_ALLOW_IPTABLES_ADDED=no
    elif [ "${FIREWALL_ALLOW_IPTABLES_V4_ADDED+x}" != x ] \
        && [ "${FIREWALL_ALLOW_IPTABLES_V6_ADDED+x}" != x ] \
        && [ "${FIREWALL_ALLOW_IPTABLES_ADDED:-no}" = yes ]; then
        if "$NETFILTER_CMD" -D INPUT -p tcp --dport "$PORT" -j ACCEPT \
            >/dev/null 2>&1; then
            if firewall_iptables_save_rules \
                "${FIREWALL_ALLOW_IPTABLES_RULES_FILE:-/etc/iptables/rules.v4}"; then
                FIREWALL_ALLOW_IPTABLES_ADDED=no
            else
                FAILED=yes
                warn "iptables 新端口规则已回滚，但持久化保存失败"
            fi
        else
            FAILED=yes
            warn "回滚本次新增的 iptables ${PORT}/tcp 规则失败"
        fi
    fi
    if [ "$FAILED" = no ]; then
        FIREWALL_ALLOW_DIRTY=no
        return 0
    fi
    return 1
}

firewall_allow_port() {
    local PORT="$1" FW_CONFIRM FAILED=no UFW_STATUS="" UFW_PORT_STATE=""
    local UFW_ALLOW_BEFORE=0 UFW_ALLOW_AFTER=0
    local RULES_FILE="" NETFILTER_CMD=iptables
    local UFW_ACTIVE=false FIREWALLD_ACTIVE=false IPTABLES_ACTIVE=false

    FIREWALL_ALLOW_UFW_ADDED=no
    FIREWALL_ALLOW_FIREWALLD_RUNTIME_ADDED=no
    FIREWALL_ALLOW_FIREWALLD_PERMANENT_ADDED=no
    FIREWALL_ALLOW_IPTABLES_ADDED=no
    FIREWALL_ALLOW_IPTABLES_V4_ADDED=no
    FIREWALL_ALLOW_IPTABLES_V6_ADDED=no
    FIREWALL_ALLOW_IPTABLES_RULES_FILE=""
    FIREWALL_ALLOW_IPTABLES_V4_RULES_FILE=""
    FIREWALL_ALLOW_IPTABLES_V6_RULES_FILE=""
    FIREWALL_ALLOW_NETFILTER_CMD=iptables
    FIREWALL_ALLOW_FIREWALLD_ZONE=""
    FIREWALL_ALLOW_DIRTY=no

    firewall_detect_backend || return 1
    NETFILTER_CMD="$FIREWALL_NETFILTER_CMD"
    RULES_FILE="${IPTABLES_RULES_FILE:-$FIREWALL_NETFILTER_RULES_DEFAULT}"
    FIREWALL_ALLOW_IPTABLES_RULES_FILE="$RULES_FILE"
    FIREWALL_ALLOW_NETFILTER_CMD="$NETFILTER_CMD"
    case "$FIREWALL_BACKEND" in
        ufw)
            UFW_ACTIVE=true
            UFW_STATUS="$FIREWALL_UFW_STATUS"
            ;;
        firewalld)
            FIREWALLD_ACTIVE=true
            FIREWALL_ALLOW_FIREWALLD_ZONE="$FIREWALL_FIREWALLD_ZONE"
            ;;
        iptables) IPTABLES_ACTIVE=true ;;
        nft-unsupported)
            error "检测到原生 nftables INPUT 丢弃策略；脚本无法安全推断并修改其规则，请先手工放行 ${PORT}/tcp"
            return 1
            ;;
        none)
        info "未检测到活跃防火墙，跳过端口放行"
        return 0
            ;;
        *)
            error "防火墙后端状态未知，拒绝继续修改 SSH 端口"
            return 1
            ;;
    esac

    echo ""
    warn "检测到活跃防火墙，是否自动放行新端口 ${PORT}/tcp？"
    read -rp "  自动放行？(Y/n，默认Y): " FW_CONFIRM
    FW_CONFIRM="${FW_CONFIRM:-y}"
    if ! echo "$FW_CONFIRM" | grep -qiE '^y(es)?$'; then
        error "未放行活跃防火墙中的新端口，已中止 SSH 端口切换；请手工放行后重试"
        return 1
    fi

    if [ "$UFW_ACTIVE" = true ]; then
        UFW_PORT_STATE=$(firewall_ufw_port_state "$UFW_STATUS" "$PORT")
        if [ "$UFW_PORT_STATE" = deny ]; then
            FAILED=yes
            error "ufw 存在 ${PORT}/tcp 的 DENY/REJECT 规则，拒绝把它误判为已放行"
        elif [ "$UFW_PORT_STATE" = policy ]; then
            FAILED=yes
            error "ufw 存在受接口或来源限制的 LIMIT 策略，拒绝自动覆盖：${PORT}/tcp"
        elif [ "$UFW_PORT_STATE" = allow ] || [ "$UFW_PORT_STATE" = limit ] \
            || [ "$UFW_PORT_STATE" = allow-limit ]; then
            info "ufw 已有 ${PORT}/tcp 放行规则"
        else
            UFW_ALLOW_BEFORE=$(firewall_ufw_allow_count "$UFW_STATUS" "$PORT")
        fi
        if [ "$UFW_PORT_STATE" = missing ] \
            && LC_ALL=C ufw insert 1 allow "${PORT}/tcp" >/dev/null 2>&1; then
            FIREWALL_ALLOW_UFW_ADDED=yes
            FIREWALL_ALLOW_DIRTY=yes
            UFW_STATUS=$(LC_ALL=C ufw status 2>/dev/null || true)
            UFW_ALLOW_AFTER=$(firewall_ufw_allow_count "$UFW_STATUS" "$PORT")
            if [ "$UFW_ALLOW_AFTER" -gt "$UFW_ALLOW_BEFORE" ] 2>/dev/null; then
                :
            fi
            if [ "$(firewall_ufw_port_state "$UFW_STATUS" "$PORT")" = allow ] \
                && [ "$UFW_ALLOW_AFTER" -gt "$UFW_ALLOW_BEFORE" ] 2>/dev/null; then
                info "ufw 已放行 ${PORT}/tcp ✓"
            else
                FAILED=yes
                error "ufw 写入后未检测到无条件放行规则：${PORT}/tcp"
            fi
        elif [ "$UFW_PORT_STATE" = missing ]; then
            FAILED=yes
            error "ufw 放行 ${PORT}/tcp 失败"
        fi
    fi
    if [ "$FIREWALLD_ACTIVE" = true ]; then
        if ! firewall-cmd --permanent --zone="$FIREWALL_ALLOW_FIREWALLD_ZONE" \
            --query-port="${PORT}/tcp" >/dev/null 2>&1; then
            if firewall-cmd --permanent --zone="$FIREWALL_ALLOW_FIREWALLD_ZONE" \
                --add-port="${PORT}/tcp" >/dev/null 2>&1; then
                FIREWALL_ALLOW_FIREWALLD_PERMANENT_ADDED=yes
                FIREWALL_ALLOW_DIRTY=yes
            else
                FAILED=yes
                error "firewalld 永久放行 ${PORT}/tcp 失败"
            fi
        fi
        if ! firewall-cmd --zone="$FIREWALL_ALLOW_FIREWALLD_ZONE" \
            --query-port="${PORT}/tcp" >/dev/null 2>&1; then
            if firewall-cmd --zone="$FIREWALL_ALLOW_FIREWALLD_ZONE" \
                --add-port="${PORT}/tcp" >/dev/null 2>&1; then
                FIREWALL_ALLOW_FIREWALLD_RUNTIME_ADDED=yes
                FIREWALL_ALLOW_DIRTY=yes
            else
                FAILED=yes
                error "firewalld 运行时放行 ${PORT}/tcp 失败"
            fi
        fi
        if [ "$FAILED" = no ]; then
            if firewall-cmd --permanent --zone="$FIREWALL_ALLOW_FIREWALLD_ZONE" \
                --query-port="${PORT}/tcp" >/dev/null 2>&1 \
                && firewall-cmd --zone="$FIREWALL_ALLOW_FIREWALLD_ZONE" \
                    --query-port="${PORT}/tcp" >/dev/null 2>&1; then
                info "firewalld 已放行 ${PORT}/tcp ✓"
            else
                FAILED=yes
                error "firewalld 写入后校验 ${PORT}/tcp 失败"
            fi
        fi
    fi
    if [ "$IPTABLES_ACTIVE" = true ]; then
        if [ "$FIREWALL_IPTABLES_V4_ACTIVE" = yes ]; then
            FIREWALL_ALLOW_IPTABLES_V4_RULES_FILE="${IPTABLES_RULES_FILE_V4:-${IPTABLES_RULES_FILE:-/etc/iptables/rules.v4}}"
            if ! firewall_iptables_persistence_available \
                "$FIREWALL_ALLOW_IPTABLES_V4_RULES_FILE"; then
                FAILED=yes
                error "无法确认 netfilter-persistent 会加载 IPv4 规则，拒绝只写运行时规则"
            elif iptables -I INPUT 1 -p tcp --dport "$PORT" -j ACCEPT \
                >/dev/null 2>&1; then
                FIREWALL_ALLOW_IPTABLES_V4_ADDED=yes
                FIREWALL_ALLOW_IPTABLES_ADDED=yes
                FIREWALL_ALLOW_DIRTY=yes
                if ! firewall_iptables_save_rules \
                    "$FIREWALL_ALLOW_IPTABLES_V4_RULES_FILE"; then
                    FAILED=yes
                    error "iptables 已放行运行时端口，但 IPv4 持久化保存失败"
                fi
            else
                FAILED=yes
                error "iptables 放行 ${PORT}/tcp 失败"
            fi
        fi
        if [ "$FIREWALL_IPTABLES_V6_ACTIVE" = yes ]; then
            FIREWALL_ALLOW_IPTABLES_V6_RULES_FILE="${IPTABLES_RULES_FILE_V6:-/etc/iptables/rules.v6}"
            if ! firewall_iptables_persistence_available \
                "$FIREWALL_ALLOW_IPTABLES_V6_RULES_FILE"; then
                FAILED=yes
                error "无法确认 netfilter-persistent 会加载 IPv6 规则，拒绝只写运行时规则"
            elif ip6tables -I INPUT 1 -p tcp --dport "$PORT" -j ACCEPT \
                >/dev/null 2>&1; then
                FIREWALL_ALLOW_IPTABLES_V6_ADDED=yes
                FIREWALL_ALLOW_IPTABLES_ADDED=yes
                FIREWALL_ALLOW_DIRTY=yes
                if ! firewall_iptables_save_rules \
                    "$FIREWALL_ALLOW_IPTABLES_V6_RULES_FILE"; then
                    FAILED=yes
                    error "ip6tables 已放行运行时端口，但 IPv6 持久化保存失败"
                fi
            else
                FAILED=yes
                error "ip6tables 放行 ${PORT}/tcp 失败"
            fi
        fi
        if [ "$FAILED" = no ]; then
            info "iptables/ip6tables 活跃地址族均已放行 ${PORT}/tcp ✓"
        fi
    fi
    if [ "$FAILED" = yes ]; then
        if firewall_rollback_allowed_port "$PORT"; then
            warn "已回滚本次新增的新端口防火墙规则"
        else
            error "部分新端口防火墙规则回滚失败，请立即手动核对 ${PORT}/tcp"
        fi
        return 1
    fi
    return 0
}

firewall_remove_port() {
    local PORT="$1"
    local CHANGED=no IPTABLES_CHANGED=no FAILED=no DELETE_COUNT=0
    local IPTABLES_V4_CHANGED=no IPTABLES_V6_CHANGED=no
    local RULES_FILE_V4="" RULES_FILE_V6=""
    local UFW_STATUS="" UFW_PORT_STATE="" UFW_ACTION=""
    local FIREWALLD_RUNTIME_PRESENT=no FIREWALLD_PERMANENT_PRESENT=no
    local FIREWALLD_ZONE=""
    FIREWALL_REMOVE_CHANGED=no

    firewall_detect_backend || return 1
    case "$FIREWALL_BACKEND" in
        none)
            return 0
            ;;
        nft-unsupported)
            error "检测到原生 nftables INPUT 丢弃策略，无法安全自动清理旧端口规则"
            return 1
            ;;
        ufw)
            UFW_STATUS="$FIREWALL_UFW_STATUS"
            UFW_PORT_STATE=$(firewall_ufw_port_state "$UFW_STATUS" "$PORT")
            case "$UFW_PORT_STATE" in
                allow) UFW_ACTION=allow ;;
                limit) UFW_ACTION=limit ;;
                allow-limit) UFW_ACTION="allow limit" ;;
                *) UFW_ACTION="" ;;
            esac
            for UFW_ACTION in $UFW_ACTION; do
                if LC_ALL=C ufw delete "$UFW_ACTION" "${PORT}/tcp" >/dev/null 2>&1; then
                    CHANGED=yes
                else
                    FAILED=yes
                    warn "ufw 旧端口 ${UFW_ACTION} 规则删除失败：${PORT}/tcp"
                fi
            done
            [ "$CHANGED" != yes ] || [ "$FAILED" = yes ] \
                || info "ufw 已关闭旧端口 ${PORT}/tcp ✓"
            ;;
        firewalld)
            FIREWALLD_ZONE="$FIREWALL_FIREWALLD_ZONE"
            if firewall-cmd --zone="$FIREWALLD_ZONE" \
                --query-port="${PORT}/tcp" >/dev/null 2>&1; then
                FIREWALLD_RUNTIME_PRESENT=yes
            fi
            if firewall-cmd --permanent --zone="$FIREWALLD_ZONE" \
                --query-port="${PORT}/tcp" >/dev/null 2>&1; then
                FIREWALLD_PERMANENT_PRESENT=yes
            fi
            if [ "$FIREWALLD_RUNTIME_PRESENT" = yes ]; then
                if firewall-cmd --zone="$FIREWALLD_ZONE" \
                    --remove-port="${PORT}/tcp" >/dev/null 2>&1; then
                    CHANGED=yes
                else
                    FAILED=yes
                    warn "firewalld 运行时旧端口规则删除失败：${PORT}/tcp"
                fi
            fi
            if [ "$FIREWALLD_PERMANENT_PRESENT" = yes ]; then
                if firewall-cmd --permanent --zone="$FIREWALLD_ZONE" \
                    --remove-port="${PORT}/tcp" >/dev/null 2>&1; then
                    CHANGED=yes
                else
                    FAILED=yes
                    warn "firewalld 永久旧端口规则删除失败：${PORT}/tcp"
                fi
            fi
            if [ "$FIREWALLD_RUNTIME_PRESENT" = yes ] \
                || [ "$FIREWALLD_PERMANENT_PRESENT" = yes ]; then
                [ "$FAILED" = yes ] \
                    || info "firewalld 已关闭旧端口 ${PORT}/tcp ✓"
            fi
            ;;
        iptables)
            RULES_FILE_V4="${IPTABLES_RULES_FILE_V4:-${IPTABLES_RULES_FILE:-/etc/iptables/rules.v4}}"
            RULES_FILE_V6="${IPTABLES_RULES_FILE_V6:-/etc/iptables/rules.v6}"
            if [ "$FIREWALL_IPTABLES_V4_ACTIVE" = yes ]; then
                if iptables -C INPUT -p tcp --dport "$PORT" -j ACCEPT \
                    >/dev/null 2>&1 \
                    && ! firewall_iptables_persistence_available "$RULES_FILE_V4"; then
                    error "无法证明 IPv4 规则会在启动时加载，拒绝只删除运行时旧端口规则"
                    return 1
                fi
                while iptables -C INPUT -p tcp --dport "$PORT" -j ACCEPT \
                    >/dev/null 2>&1; do
                    if ! iptables -D INPUT -p tcp --dport "$PORT" -j ACCEPT \
                        >/dev/null 2>&1; then
                        FAILED=yes
                        warn "iptables 旧端口规则删除失败：${PORT}/tcp"
                        break
                    fi
                    CHANGED=yes
                    IPTABLES_CHANGED=yes
                    IPTABLES_V4_CHANGED=yes
                    DELETE_COUNT=$((DELETE_COUNT+1))
                    if [ "$DELETE_COUNT" -ge 256 ]; then
                        FAILED=yes
                        warn "iptables 旧端口规则数量异常，已停止继续删除：${PORT}/tcp"
                        break
                    fi
                done
                if [ "$IPTABLES_V4_CHANGED" = yes ] \
                    && ! firewall_iptables_save_rules "$RULES_FILE_V4"; then
                    warn "IPv4 运行时规则已更新，但持久化保存失败"
                    return 1
                fi
            fi
            if [ "$FIREWALL_IPTABLES_V6_ACTIVE" = yes ]; then
                if ip6tables -C INPUT -p tcp --dport "$PORT" -j ACCEPT \
                    >/dev/null 2>&1 \
                    && ! firewall_iptables_persistence_available "$RULES_FILE_V6"; then
                    error "无法证明 IPv6 规则会在启动时加载，拒绝只删除运行时旧端口规则"
                    return 1
                fi
                while ip6tables -C INPUT -p tcp --dport "$PORT" -j ACCEPT \
                    >/dev/null 2>&1; do
                    if ! ip6tables -D INPUT -p tcp --dport "$PORT" -j ACCEPT \
                        >/dev/null 2>&1; then
                        FAILED=yes
                        warn "ip6tables 旧端口规则删除失败：${PORT}/tcp"
                        break
                    fi
                    CHANGED=yes
                    IPTABLES_CHANGED=yes
                    IPTABLES_V6_CHANGED=yes
                    DELETE_COUNT=$((DELETE_COUNT+1))
                    if [ "$DELETE_COUNT" -ge 256 ]; then
                        FAILED=yes
                        warn "ip6tables 旧端口规则数量异常，已停止继续删除：${PORT}/tcp"
                        break
                    fi
                done
                if [ "$IPTABLES_V6_CHANGED" = yes ] \
                    && ! firewall_iptables_save_rules "$RULES_FILE_V6"; then
                    warn "IPv6 运行时规则已更新，但持久化保存失败"
                    return 1
                fi
            fi
            [ "$IPTABLES_CHANGED" != yes ] \
                || info "iptables 已关闭旧端口 ${PORT}/tcp ✓"
            ;;
    esac

    FIREWALL_REMOVE_CHANGED="$CHANGED"
    [ "$FAILED" = no ]
}
